# four_numbers: a FOX model for GroundFOX from DCP Rosetta.
#
# Given a list of up to four distinct integers between 1 and 10 (inclusive), the task is to
# find a list of three integers (also between 1 and 10, inclusive) such that all the original
# numbers can be generated by summing *subsets* of these three numbers. For example, if the
# input is [1, 3, 7, 8], a valid solution is [1, 2, 5], because:
#
# * 1 = 1 * 3 = 1 + 2 * 7 = 2 + 5 * 8 = 1 + 2 + 5
#
# Print the list of three integers (x) that satisfies the above conditions.
#
# The theory is grounded by GroundFOX into CNF with a CertiFOX proof (checked by checkfox) and
# solved by a SAT solver; structure(instance) supplies the input relations from the data.
#   https://dcp-bench.github.io/DCP-Rosetta/problems/four_numbers.html
# Run (groundfox from https://gitlab.kuleuven.be/krr/software/groundfox-checkfox, pip install python-sat):
#   python dcp_fox.py model.py four_numbers.json --check

FOX = """
invocabulary { Pos/1 Val/1 Tv/1 Idx/1 Mask/1 Add/3 Eq/2 }
outvocabulary { x/2 P/2 Hit/2 }
theory {
    ! j [Pos(j)] : ? v [Val(v)] : x(j, v).
    ! j [Pos(j)] : ! v [Val(v)] : ! w [Val(w) & v ~= w] : ~x(j, v) | ~x(j, w).
    ! u [Val(u)] : ~x(0, u) | P(1, u).
    ! u [Val(u)] : ~x(1, u) | P(2, u).
    ! u [Val(u)] : ~x(2, u) | P(4, u).
    ! u [Val(u)] : ! w [Val(w)] : ! t [Add(u, w, t)] : ~x(0, u) | ~x(1, w) | P(3, t).
    ! u [Val(u)] : ! w [Val(w)] : ! t [Add(u, w, t)] : ~x(0, u) | ~x(2, w) | P(5, t).
    ! u [Val(u)] : ! w [Val(w)] : ! t [Add(u, w, t)] : ~x(1, u) | ~x(2, w) | P(6, t).
    ! u [Tv(u)] : ! w [Val(w)] : ! t [Add(u, w, t)] : ~P(3, u) | ~x(2, w) | P(7, t).
    ! i [Idx(i)] : ? m [Mask(m)] : Hit(i, m).
    ! i [Idx(i)] : ! m [Mask(m)] : ! t [Tv(t) & ~Eq(i, t)] : ~Hit(i, m) | ~P(m, t).
}
"""

FLAGS = []


def structure(instance):
    numbers = instance["numbers"]
    add = [(u, w, u + w) for u in range(1, 31) for w in range(1, 31) if u + w <= 30]
    return {
        "domain": range(31),
        "Pos": range(3),
        "Val": range(1, 11),
        "Tv": range(1, 31),
        "Idx": range(len(numbers)),
        "Mask": range(1, 8),
        "Add": add,
        "Eq": [(i, n) for i, n in enumerate(numbers)],
    }
